// mapped column into the record and pass 2b default-fills the mapped fields that had no column.
void __stdcall TXT_ParseDataAndPutIntoStructure(D2BinFieldExcelStrc * pBinFieldExcel, D2BinFieldInputStrc * pBinFieldInput, char * pRecord, size_t nLinesCount, int nEndOffset) {
    uint16_t uVar1;
    int nMappedFieldCount;
    int nLinkIndex;
    int32_t nResolvedLinkId;
    char cCurChar;
    uint32_t nFieldValue;
    int nLinkCodeLen;
    int nRawCodeLen;
    int nClassCodeLen;
    char* pParseBufCursor;
    int nScanColIndex;
    char* pFieldCursor;
    char* pCurDataPos;
    char* pDstChar;
    char* pFieldDst;
    char* pCopyCursor;
    int nLineIndex;
    int nColIndex;
    uint32_t dwCodePadded;
    uint16_t aColumnFieldMap[280];
    char aFieldParseBuf[288];
    uint32_t dwCodeBuf;
    char cLinkNameTerm;
    PFN_TxtFieldLinker pfnLinker;
    PFN_TxtFieldLinker pfnDefaultLinker;
    eD2BinFieldInputType eFieldType3;
    int nOffset;
    size_t nFieldSize;
    int nColumnCount;
    int nFillOffset;
    size_t nNameSize;
    eD2BinFieldInputType eFieldType;
    eD2BinFieldInputType eFieldType2;
    char* pFieldEnd;
    PFN_TxtKeyToWord pfnKeyToWord;
    bool bHasLinkFields;
    uint32_t dwCode;
    uint16_t nFieldMapIdx;
    uint32_t dwSecurityCookie;
    dwSecurityCookie = DEFAULT_SECURITY_COOKIE ^ (uintptr_t)0;
    char* pCurrentRecord;
    pCurrentRecord = pRecord;
    if (!nLinesCount) {
      ErrorManager::ERROR_UnrecoverableInternalError_Halt("", ErrorManager::GetInstructionPointer(), 0x112);
      exit(-1);
    } else {
      if (nEndOffset) {
        nMappedFieldCount = FOG_ParseBinField((int)aColumnFieldMap, pBinFieldExcel, pBinFieldInput);
        nColumnCount = pBinFieldExcel->nColumnCount;
        bHasLinkFields = false;
        nScanColIndex = 0;
        if (0 < nColumnCount) {
          do {
            if (aColumnFieldMap[nScanColIndex] != 0x7fff && true) {
              switch (pBinFieldInput[aColumnFieldMap[nScanColIndex]].eType) {
                case FIELDTYPE_CODE4:

                case FIELDTYPE_CODE1:

                case FIELDTYPE_CODE2:

                case FIELDTYPE_NAME_I:

                case FIELDTYPE_NAME_I_WORD:

                case FIELDTYPE_NAME_I_INT:
                  bHasLinkFields = true;
              }
            }

            nScanColIndex++;
          } while (nScanColIndex < nColumnCount);
        }
        if (bHasLinkFields) {
          pCurDataPos = pBinFieldExcel->pDataStart;
          nLineIndex = 0;
          if (0 < (int)pBinFieldExcel->nLinesCount) {
            do {
              nColIndex = 0;
              if (0 < nColumnCount) {
                do {
                  nFieldMapIdx = aColumnFieldMap[nColIndex];
                  if (nFieldMapIdx == 0x7fff) {
                    cCurChar = *pCurDataPos;
                    while (cCurChar != '\0') {
                      pCurDataPos++;
                      cCurChar = *pCurDataPos;
                    }

                    next_column:
                    pCurDataPos++;
                  } else {
                    pFieldDst = pCurrentRecord + pBinFieldInput[nFieldMapIdx].nOffset;
                    if (false) {
                      default_case:
                      cCurChar = *pCurDataPos;
                      while (cCurChar != '\0') {
                        pCurDataPos++;
                        cCurChar = *pCurDataPos;
                      }

                      goto next_column;
                    }

                    switch (pBinFieldInput[nFieldMapIdx].eType) {
                      case FIELDTYPE_CODE4:

                      case FIELDTYPE_CODE1:

                      case FIELDTYPE_CODE2:
                        dwCodeBuf = 0;
                      cCurChar = *pCurDataPos;
                      nLinkCodeLen = 0;
                      dwCode = dwCodeBuf;
                      read_link_code_char:
                      dwCodeBuf = dwCode;
                      if (cCurChar != '\0') {
                        if (nLinkCodeLen < 4) {
                          pCurDataPos++;
                          *(char*)((uintptr_t)&dwCodeBuf + nLinkCodeLen) = cCurChar;
                          cCurChar = *pCurDataPos;
                          nLinkCodeLen++;
                          dwCode = dwCodeBuf;
                          goto read_link_code_char;
                        }

                        cCurChar = *pCurDataPos;
                        while (cCurChar != '\0') {
                          pCurDataPos++;
                          cCurChar = *pCurDataPos;
                        }
                      }

                      pCurDataPos++;
                      if ((char)dwCode == '\0') {
                        dwCodePadded = 0x20202020;
                      } else if ((char)(dwCode >> 8) == '\0') {
                        *(uint16_t*)(char*)&dwCodePadded = (uint16_t)((uint16_t)(uint8_t)0x20 << 8 | (uint16_t)(uint8_t)(char)dwCode);
                        d2_store24((char*)&dwCodePadded, (uint32_t)((uint32_t)((uint32_t)(uint8_t)0x20 << 16 | (uint32_t)(uint16_t)dwCodePadded) & 0xffffffu));
                        dwCodePadded = (uint32_t)((uint32_t)(uint8_t)0x20 << 24 | (uint32_t)((uint32_t)dwCodePadded & 0xffffffu));
                      } else {
                        *(uint8_t*)((char*)&dwCodeBuf + 2) = (char)(dwCode >> 0x10);
                        *(uint16_t*)(char*)&dwCodePadded = (uint16_t)dwCode;
                        if (*(uint8_t*)((char*)&dwCodeBuf + 2) == '\0') {
                          d2_store24((char*)&dwCodePadded, (uint32_t)((uint32_t)((uint32_t)(uint8_t)0x20 << 16 | (uint32_t)(uint16_t)dwCodePadded) & 0xffffffu));
                          dwCodePadded = (uint32_t)((uint32_t)(uint8_t)0x20 << 24 | (uint32_t)((uint32_t)dwCodePadded & 0xffffffu));
                        } else {
                          d2_store24((char*)&dwCodePadded, (uint32_t)dwCode & 0xffffffu);
                          dwCodePadded = (uint32_t)((uint32_t)(uint8_t)0x20 << 24 | (uint32_t)((uint32_t)dwCodePadded & 0xffffffu));
                          *(uint8_t*)((char*)&dwCodeBuf + 3) = (char)(dwCode >> 0x18);
                          if (*(uint8_t*)((char*)&dwCodeBuf + 3) != '\0') {
                            dwCodePadded = dwCode;
                          }
                        }
                      }

                      nLinkIndex = FillUpTxtLinkSub0x08(*(D2TxtLinkStrc**)pBinFieldInput[nFieldMapIdx].fpLinker, (char*)dwCodePadded);
                      eFieldType3 = pBinFieldInput[nFieldMapIdx].eType;
                      switch (eFieldType3) {
                        case FIELDTYPE_CODE4:
                          {
                            *(uint32_t*)pFieldDst = dwCodePadded;
                            break;
                          }
                        case FIELDTYPE_CODE1:
                          {
                            if (0xff < nLinkIndex) {
                              ErrorManager::ERROR_UnrecoverableInternalError_Halt("", ErrorManager::GetInstructionPointer(), 0x156);
                              exit(-1);
                            }

                            *pFieldDst = (char)dwCodePadded;
                            break;
                          }
                        case FIELDTYPE_CODE2:
                          {
                            if (0xffff < nLinkIndex) {
                              ErrorManager::ERROR_UnrecoverableInternalError_Halt("", ErrorManager::GetInstructionPointer(), 0x15a);
                              exit(-1);
                            }

                            *(uint16_t*)pFieldDst = (uint16_t)dwCodePadded;
                            break;
                          }
                      }

                      break;
                      default:
                        goto default_case;
                      case FIELDTYPE_NAME_I:
                        cCurChar = *pCurDataPos;
                      nNameSize = pBinFieldInput[nFieldMapIdx].nSize;
                      for (pCopyCursor = pFieldDst; cCurChar != '\0' && pCopyCursor < pFieldDst + (nNameSize - 1); pCopyCursor++) {
                        pCurDataPos++;
                        *pCopyCursor = cCurChar;
                        cCurChar = *pCurDataPos;
                      }

                      *pCopyCursor = '\0';
                      cCurChar = *pCurDataPos;
                      while (cCurChar != '\0') {
                        pCurDataPos++;
                        cCurChar = *pCurDataPos;
                      }

                      pCurDataPos++;
                      FOG_ParseStringField(*(D2TxtLinkStrc**)pBinFieldInput[nFieldMapIdx].fpLinker, pFieldDst);
                      break;
                      case FIELDTYPE_NAME_I_WORD:

                      case FIELDTYPE_NAME_I_INT:
                        cCurChar = *pCurDataPos;
                      for (pDstChar = aFieldParseBuf + 0x100; cCurChar != '\0' && pDstChar < aFieldParseBuf + 0x11f; pDstChar++) {
                        pCurDataPos++;
                        *pDstChar = cCurChar;
                        cCurChar = *pCurDataPos;
                      }

                      cCurChar = *pCurDataPos;
                      *pDstChar = '\0';
                      while (cCurChar != '\0') {
                        pCurDataPos++;
                        cCurChar = *pCurDataPos;
                      }

                      pCurDataPos++;
                      nResolvedLinkId = FOG_ParseTxtLink(*(D2TxtLinkStrc**)pBinFieldInput[nFieldMapIdx].fpLinker, aFieldParseBuf + 0x100);
                      if (pBinFieldInput[nFieldMapIdx].eType == FIELDTYPE_NAME_I_WORD) {
                        *(short int*)(pCurrentRecord + pBinFieldInput[nFieldMapIdx].nOffset) = (short int)nResolvedLinkId;
                      } else {
                        *(int32_t*)(pCurrentRecord + pBinFieldInput[nFieldMapIdx].nOffset) = nResolvedLinkId;
                      }
                    }
                  }

                  nColumnCount = pBinFieldExcel->nColumnCount;
                  nColIndex++;
                } while (nColIndex < nColumnCount);
              }
              if (*pCurDataPos != '\n') {
                ErrorManager::ERROR_UnrecoverableInternalError_Halt("", ErrorManager::GetInstructionPointer(), 0x185);
                exit(-1);
              }

              pCurrentRecord += nEndOffset;
              nLineIndex++;
              pCurDataPos++;
            } while (nLineIndex < (int)pBinFieldExcel->nLinesCount);
          }
        }

        pCurDataPos = pBinFieldExcel->pDataStart;
        nLineIndex = 0;
        if ((int)pBinFieldExcel->nLinesCount < 1) {
          Debug::GuardStack();
          return;
        }

        do {
          nColIndex = 0;
          pDstChar = pCurDataPos;
          if (0 < pBinFieldExcel->nColumnCount) {
            do {
              nFieldMapIdx = aColumnFieldMap[nColIndex];
              if (nFieldMapIdx == 0x7fff) {
                cCurChar = *pCurDataPos;
                while (cCurChar != '\0') {
                  pCurDataPos++;
                  cCurChar = *pCurDataPos;
                }

                pDstChar = pCurDataPos + 1;
              } else {
                nOffset = pBinFieldInput[nFieldMapIdx].nOffset;
                pFieldCursor = pRecord + nOffset;
                nFieldSize = pBinFieldInput[nFieldMapIdx].nSize;
                pFieldEnd = pFieldCursor + nFieldSize;
                switch (TXT_ParseFieldTypeCaseIndex[pBinFieldInput[nFieldMapIdx].eType - 1]) {
                  case 0:
                    cCurChar = *pCurDataPos;
                  pDstChar = pCurDataPos;
                  if (cCurChar == '\0') {
                    terminate_string:
                    pDstChar = pCurDataPos + 1;
                    *pFieldCursor = '\0';
                  } else {
                    do {
                      pCurDataPos = pDstChar;
                      if (pFieldEnd <= pFieldCursor) {
                        cCurChar = *pCurDataPos;
                        while (cCurChar != '\0') {
                          pCurDataPos++;
                          cCurChar = *pCurDataPos;
                        }

                        goto terminate_string;
                      }

                      *pFieldCursor = cCurChar;
                      cCurChar = pCurDataPos[1];
                      pFieldCursor++;
                      pDstChar = pCurDataPos + 1;
                    } while (cCurChar != '\0');

                    pDstChar = pCurDataPos + 2;
                    *pFieldCursor = '\0';
                  }

                  break;
                  case 1:
                    pDstChar = pCurDataPos;
                  if (*pCurDataPos == '-') {
                    pDstChar = pCurDataPos + 1;
                  }

                  nFieldValue = 0;
                  cCurChar = *pDstChar;
                  while (cCurChar != '\0') {
                    pDstChar++;
                    nFieldValue = cCurChar - 0x30 + nFieldValue * 10;
                    cCurChar = *pDstChar;
                  }

                  if (*pCurDataPos == '-') {
                    nFieldValue = -nFieldValue;
                  }

                  pDstChar++;
                  switch (pBinFieldInput[nFieldMapIdx].eType) {
                    case FIELDTYPE_INT:

                    case FIELDTYPE_UINT:
                      goto store_int;
                    case FIELDTYPE_SHORT:
                      case_FIELDTYPE_SHORT:
                      *(short int*)pFieldCursor = (short int)nFieldValue;
                    break;
                    case FIELDTYPE_CHAR:

                    case FIELDTYPE_BYTE:
                      case_FIELDTYPE_CHAR:
                      *pFieldCursor = (char)nFieldValue;
                    break;
                    case FIELDTYPE_BOOL:
                      if (pCurDataPos + 1 != pDstChar) {
                        *pFieldCursor = (char)nFieldValue;
                      }
                    break;
                    case FIELDTYPE_BIT:
                      if (!nFieldValue) {
                        BitBuffer::UnsetBitAtOffset(pFieldCursor, nFieldSize);
                      } else {
                        BitBuffer::SetBitAtOffset(pFieldCursor, nFieldSize);
                      }
                  }

                  break;
                  case 2:
                    nRawCodeLen = 0;
                  dwCodeBuf = 0;
                  cCurChar = *pCurDataPos;
                  dwCode = dwCodeBuf;
                  read_raw_code_char:
                  dwCodeBuf = dwCode;
                  if (cCurChar != '\0') {
                    if (nRawCodeLen < 4) {
                      pCurDataPos++;
                      *(char*)((uintptr_t)&dwCodeBuf + nRawCodeLen) = cCurChar;
                      cCurChar = *pCurDataPos;
                      nRawCodeLen++;
                      dwCode = dwCodeBuf;
                      goto read_raw_code_char;
                    }

                    cCurChar = *pCurDataPos;
                    while (cCurChar != '\0') {
                      pCurDataPos++;
                      cCurChar = *pCurDataPos;
                    }
                  }

                  *(uint8_t*)(char*)&dwCodeBuf = (char)dwCode;
                  pDstChar = pCurDataPos + 1;
                  if ((char)dwCodeBuf == '\0') {
                    memcpy(pRecord + nOffset, "    ", 4);
                  } else {
                    *pFieldCursor = (char)dwCodeBuf;
                    cCurChar = (char)(dwCode >> 8);
                    if (cCurChar == '\0') {
                      pFieldCursor[1] = ' ';
                      pFieldCursor[2] = ' ';
                      pFieldCursor[3] = ' ';
                    } else {
                      pFieldCursor[1] = cCurChar;
                      *(uint8_t*)((char*)&dwCodeBuf + 2) = (char)(dwCode >> 0x10);
                      if (*(uint8_t*)((char*)&dwCodeBuf + 2) == '\0') {
                        pFieldCursor[2] = ' ';
                        pFieldCursor[3] = ' ';
                      } else {
                        pFieldCursor[2] = *(uint8_t*)((char*)&dwCodeBuf + 2);
                        *(uint8_t*)((char*)&dwCodeBuf + 3) = (char)(dwCode >> 0x18);
                        if (*(uint8_t*)((char*)&dwCodeBuf + 3) == '\0') {
                          pFieldCursor[3] = ' ';
                        } else {
                          pFieldCursor[3] = *(uint8_t*)((char*)&dwCodeBuf + 3);
                        }
                      }
                    }
                  }

                  break;
                  case 3:
                    cCurChar = *pCurDataPos;
                  while (cCurChar != '\0') {
                    pCurDataPos++;
                    cCurChar = *pCurDataPos;
                  }

                  pDstChar = pCurDataPos + 1;
                  break;
                  case 4:
                    dwCodeBuf = 0;
                  cCurChar = *pCurDataPos;
                  nClassCodeLen = 0;
                  if (cCurChar != '\0') {
                    read_lookup_code_char:
                    if (nClassCodeLen < 4) {
                      pCurDataPos++;
                      *(char*)((uintptr_t)&dwCodeBuf + nClassCodeLen) = cCurChar;
                      cCurChar = *pCurDataPos;
                      nClassCodeLen++;
                      if (cCurChar == '\0') {
                        goto pad_and_lookup_code;
                      }

                      goto read_lookup_code_char;
                    }
                    cCurChar = *pCurDataPos;
                    while (cCurChar != '\0') {
                      pCurDataPos++;
                      cCurChar = *pCurDataPos;
                    }
                  }

                  pad_and_lookup_code:
                  pDstChar = pCurDataPos + 1;
                  if ((char)dwCodeBuf == '\0') {
                    dwCodePadded = 0x20202020;
                  } else if ((char)(dwCodeBuf >> 8) == '\0') {
                    *(uint16_t*)(char*)&dwCodePadded = (uint16_t)((uint16_t)(uint8_t)0x20 << 8 | (uint16_t)(uint8_t)(char)dwCodeBuf);
                    d2_store24((char*)&dwCodePadded, (uint32_t)((uint32_t)((uint32_t)(uint8_t)0x20 << 16 | (uint32_t)(uint16_t)dwCodePadded) & 0xffffffu));
                    dwCodePadded = (uint32_t)((uint32_t)(uint8_t)0x20 << 24 | (uint32_t)((uint32_t)dwCodePadded & 0xffffffu));
                  } else {
                    *(uint16_t*)(char*)&dwCodePadded = (uint16_t)dwCodeBuf;
                    if (*(uint8_t*)((char*)&dwCodeBuf + 2) == '\0') {
                      d2_store24((char*)&dwCodePadded, (uint32_t)((uint32_t)((uint32_t)(uint8_t)0x20 << 16 | (uint32_t)(uint16_t)dwCodePadded) & 0xffffffu));
                      dwCodePadded = (uint32_t)((uint32_t)(uint8_t)0x20 << 24 | (uint32_t)((uint32_t)dwCodePadded & 0xffffffu));
                    } else {
                      d2_store24((char*)&dwCodePadded, (uint32_t)dwCodeBuf & 0xffffffu);
                      dwCodePadded = (uint32_t)((uint32_t)(uint8_t)0x20 << 24 | (uint32_t)((uint32_t)dwCodePadded & 0xffffffu));
                      if (*(uint8_t*)((char*)&dwCodeBuf + 3) != '\0') {
                        dwCodePadded = dwCodeBuf;
                      }
                    }
                  }

                  nFieldValue = GetClassIdFromName(*(D2TxtLinkStrc**)pBinFieldInput[nFieldMapIdx].fpLinker, dwCodePadded, 1);
                  eFieldType2 = pBinFieldInput[nFieldMapIdx].eType;
                  if (eFieldType2 == FIELDTYPE_CODE_INT) {
                    store_int:
                    *(uint32_t*)pFieldCursor = nFieldValue;
                  } else {
                    if (eFieldType2 == FIELDTYPE_CODE_CHAR) {
                      goto case_FIELDTYPE_CHAR;
                    }
                    if (eFieldType2 == FIELDTYPE_CODE_SHORT) {
                      *(short int*)pFieldCursor = (short int)nFieldValue;
                    }
                  }

                  break;
                  case 5:
                    cCurChar = *pCurDataPos;
                  for (pDstChar = (char*)&dwCodeBuf; cCurChar != '\0' && pDstChar < &cLinkNameTerm; pDstChar++) {
                    pCurDataPos++;
                    *pDstChar = cCurChar;
                    cCurChar = *pCurDataPos;
                  }

                  *pDstChar = '\0';
                  cCurChar = *pCurDataPos;
                  while (cCurChar != '\0') {
                    pCurDataPos++;
                    cCurChar = *pCurDataPos;
                  }

                  pDstChar = pCurDataPos + 1;
                  nFieldValue = GetLinkNodeIndex(*(D2TxtLinkStrc**)pBinFieldInput[nFieldMapIdx].fpLinker, (char*)&dwCodeBuf, 1);
                  eFieldType = pBinFieldInput[nFieldMapIdx].eType;
                  if (eFieldType == FIELDTYPE_NAME_INT) {
                    goto store_int;
                  }
                  if (eFieldType == FIELDTYPE_NAME_SHORT) {
                    goto case_FIELDTYPE_SHORT;
                  }
                  if (eFieldType == FIELDTYPE_NAME_CHAR) {
                    goto case_FIELDTYPE_CHAR;
                  }

                  break;
                  case 6:
                    cCurChar = *pCurDataPos;
                  pParseBufCursor = aFieldParseBuf;
                  read_key_char:
                  if (cCurChar != '\0') {
                    if (pParseBufCursor < aFieldParseBuf + 0x100) {
                      pCurDataPos++;
                      *pParseBufCursor = cCurChar;
                      cCurChar = *pCurDataPos;
                      pParseBufCursor++;
                      goto read_key_char;
                    }

                    cCurChar = *pCurDataPos;
                    while (cCurChar != '\0') {
                      pCurDataPos++;
                      cCurChar = *pCurDataPos;
                    }
                  }
                  pfnKeyToWord = (PFN_TxtKeyToWord)pBinFieldInput[nFieldMapIdx].fpLinker;
                  pDstChar = pCurDataPos + 1;
                  *pParseBufCursor = '\0';
                  if (pfnKeyToWord) {
                    uVar1 = (*pfnKeyToWord)(aFieldParseBuf);
                    nFieldValue = (uint32_t)uVar1;
                    goto case_FIELDTYPE_SHORT;
                  }

                  break;
                  case 7:
                    cCurChar = *pCurDataPos;
                  pParseBufCursor = aFieldParseBuf;
                  read_linker_arg_char:
                  if (cCurChar != '\0') {
                    if (pParseBufCursor < aFieldParseBuf + 0x100) {
                      pCurDataPos++;
                      *pParseBufCursor = cCurChar;
                      cCurChar = *pCurDataPos;
                      pParseBufCursor++;
                      goto read_linker_arg_char;
                    }

                    cCurChar = *pCurDataPos;
                    while (cCurChar != '\0') {
                      pCurDataPos++;
                      cCurChar = *pCurDataPos;
                    }
                  }
                  pfnLinker = (PFN_TxtFieldLinker)pBinFieldInput[nFieldMapIdx].fpLinker;
                  pDstChar = pCurDataPos + 1;
                  *pParseBufCursor = '\0';
                  if (pfnLinker) {
                    (*pfnLinker)(aFieldParseBuf, pRecord, nOffset, nFieldSize, nLineIndex, nColIndex);
                  }

                  break;
                }
              }

              nColIndex++;
              pCurDataPos = pDstChar;
            } while (nColIndex < pBinFieldExcel->nColumnCount);
          }

          for (; nColIndex < nMappedFieldCount; nColIndex++) {
            nFieldMapIdx = aColumnFieldMap[nColIndex];
            nFillOffset = pBinFieldInput[nFieldMapIdx].nOffset;
            switch (pBinFieldInput[nFieldMapIdx].eType) {
              default:
                pRecord[nFillOffset] = '\0';
              break;
              case FIELDTYPE_INT:

              case FIELDTYPE_UINT:

              case FIELDTYPE_RAW4:

              case FIELDTYPE_CODE4:

              case FIELDTYPE_NAME_I_INT:
                pCurDataPos = pRecord + nFillOffset;
              memset(pCurDataPos, 0, 4 * sizeof(pCurDataPos[0]));
              break;
              case FIELDTYPE_SHORT:

              case FIELDTYPE_CODE2:

              case FIELDTYPE_NAME_I_WORD:

              case FIELDTYPE_KEY_WORD:
                (pRecord + nFillOffset)[0] = '\0';
              (pRecord + nFillOffset)[1] = '\0';
              break;
              case FIELDTYPE_CODE_INT:
                pCurDataPos = pRecord + nFillOffset;
              pCurDataPos[0] = -1;
              pCurDataPos[1] = -1;
              pCurDataPos[2] = -1;
              pCurDataPos[3] = -1;
              break;
              case FIELDTYPE_CODE_CHAR:

              case FIELDTYPE_NAME_CHAR:
                pRecord[nFillOffset] = -1;
              break;
              case FIELDTYPE_CODE_SHORT:

              case FIELDTYPE_NAME_SHORT:
                (pRecord + nFillOffset)[0] = -1;
              (pRecord + nFillOffset)[1] = -1;
              break;
              case FIELDTYPE_NAME_INT:
                pCurDataPos = pRecord + nFillOffset;
              pCurDataPos[0] = -1;
              pCurDataPos[1] = -1;
              pCurDataPos[2] = -1;
              pCurDataPos[3] = -1;
              break;
              case FIELDTYPE_LINKER_BIT:

              case FIELDTYPE_LINKER_UNK:

              case FIELDTYPE_LINKER_INT:
                pfnDefaultLinker = (PFN_TxtFieldLinker)pBinFieldInput[nFieldMapIdx].fpLinker;
              if (pfnDefaultLinker) {
                (*pfnDefaultLinker)(nullptr, pRecord, nFillOffset, pBinFieldInput[nFieldMapIdx].nSize, nLineIndex, nColIndex);
              }

              break;
              case FIELDTYPE_BIT:
                break;
            }
          }

          if (*pDstChar != '\n') {
            ErrorManager::ERROR_UnrecoverableInternalError_Halt("", ErrorManager::GetInstructionPointer(), 0x286);
            exit(-1);
          }

          pRecord += nEndOffset;
          nLineIndex++;
          pCurDataPos = pDstChar + 1;
          if ((int)pBinFieldExcel->nLinesCount <= nLineIndex) {
            Debug::GuardStack();
            return;
          }
        } while (true);
      }

      ErrorManager::ERROR_UnrecoverableInternalError_Halt("", ErrorManager::GetInstructionPointer(), 0x113);
      exit(-1);
    }
}

